class AvgPartition:
    def __init__(self, lst, limit):
        self._lst = lst
        self._limit = limit

    # Encapsulate Field
    @property
    def lst(self):
        return self._lst

    @property
    def limit(self):
        return self._limit

    def _get_size_and_remainder(self):
        """Encapsulate Collection / Extract Method: private helper to compute partition size info"""
        size = len(self._lst) // self._limit
        remainder = len(self._lst) % self._limit
        return size, remainder

    def setNum(self):
        """Extract Method: original logic moved to _get_size_and_remainder, setNum delegates"""
        return self._get_size_and_remainder()

    def _compute_start(self, index, size, remainder):
        """Extract Method: isolate start computation"""
        return index * size + min(index, remainder)

    def _compute_end(self, start, size, index, remainder):
        """Extract Method: isolate end computation with guard clause style"""
        end = start + size
        if index + 1 <= remainder:
            end += 1
        return end

    def get(self, index):
        """
        Refactorings applied:
        - Extract Method: _compute_start, _compute_end, _get_size_and_remainder
        - Replace Temp with Query: sizes fetched directly when needed
        - Introduce Explaining Variable: 'size', 'remainder' are meaningful
        - Replace Nested Conditional with Guard Clauses: not nested, but conditional handled cleanly in _compute_end
        """
        size, remainder = self._get_size_and_remainder()
        start = self._compute_start(index, size, remainder)
        end = self._compute_end(start, size, index, remainder)
        return self._lst[start:end]
